mapper.sql:
WHERE d.kind IN ('SALES_OUT', 'SALES_RETURN')('PURCHASE_IN', 'PURCHASE_RETURN')
  AND d.biz_date >= #{q.begin} AND d.biz_date <= #{q.end}
AND d.partner_id = #{q.partnerId}
AND o.salesman_id = #{q.salesmanId}
AND o.salesman_id IS NULL
AND i.material_id = #{q.materialId}
AND m.category = #{q.category}
AND (m.category IS NULL OR m.category = '')
AND m.brand = #{q.brand}
AND (m.brand IS NULL OR m.brand = '')
AND p.region = #{q.region}
AND (p.region IS NULL OR p.region = '')
AND COALESCE(i.warehouse_id, d.warehouse_id) = #{q.warehouseId}

    AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))

mapper.select:
SELECT b.partner_id AS "partnerId", p.name AS "partnerName", SUM(b.amount - b.settled_amount) AS "amount" FROM fin_bill b
LEFT JOIN scm_customer p ON p.id = b.partner_id LEFT JOIN scm_supplier p ON p.id = b.partner_id
WHERE b.kind = #{kind} AND b.status <> 'SETTLED' GROUP BY b.partner_id, p.name HAVING SUM(b.amount - b.settled_amount) > 0 ORDER BY SUM(b.amount - b.settled_amount) DESC, b.partner_id LIMIT #{limit}

mapper.sql:
AND m.is_template = 0
AND m.category = #{q.category}
AND m.brand = #{q.brand}

    AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))

mapper.select:
SELECT d.partner_id AS "customerId", c.code AS "code", c.name AS "name", MAX(CASE WHEN d.kind = 'SALES_OUT' THEN d.biz_date END) AS "lastDate", COUNT(DISTINCT CASE WHEN d.kind = 'SALES_OUT' THEN d.id END) AS "frequency", SUM(CASE WHEN d.kind = 'SALES_OUT' THEN 1 ELSE -1 END * (i.amount - i.tax_amount)) AS "monetary" FROM scm_trade_doc_item i JOIN scm_trade_doc d ON d.id = i.doc_id JOIN scm_customer c ON c.id = d.partner_id WHERE d.kind IN ('SALES_OUT', 'SALES_RETURN') AND d.biz_date >= #{q.begin} AND d.biz_date <= #{q.end} AND c.region = #{q.region}
AND (c.code LIKE CONCAT('%', #{q.keyword}, '%') OR c.name LIKE CONCAT('%', #{q.keyword}, '%'))
GROUP BY d.partner_id, c.code, c.name HAVING COUNT(DISTINCT CASE WHEN d.kind = 'SALES_OUT' THEN d.id END) > 0
